-- 013: the copilot's lanes (backend/src/copilot/lanes/): each lane owns its flagged turns, replay cases, eval sets and judge setting.
-- Generated by scripts/lanes-schema.mjs; every statement is create-if-not-exists. Content shared by the lanes is not here.

-- lane: strong
create table if not exists copilot_strong_flagged_turns (id bigserial primary key, created_at timestamptz not null default now(), session text, channel text, input text not null, output text, model text, tools text[], reason text not null, trace_id text);
create table if not exists copilot_strong_replay_cases (id bigserial primary key, created_at timestamptz not null default now(), name text not null unique, lines jsonb not null, checks jsonb not null, source_flag bigint);
create table if not exists copilot_strong_eval_sets (id bigserial primary key, created_at timestamptz not null default now(), name text not null, case_ids bigint[] not null, notes text);
create table if not exists copilot_strong_judge_settings (id bigserial primary key, updated_at timestamptz not null default now(), judge_model text not null, rubric text not null, embedder text not null, reranker text not null);

